from collections import defaultdict, deque

def findOrder(dict, N, K):
    # Collect all unique characters
    chars = set()
    for word in dict:
        for c in word:
            chars.add(c)
    chars = sorted(chars)  # To ensure consistent order for topological sort

    # Build graph and in-degree count
    graph = defaultdict(set)
    in_degree = {c: 0 for c in chars}

    for i in range(N - 1):
        word1 = dict[i]
        word2 = dict[i + 1]
        min_len = min(len(word1), len(word2))
        for j in range(min_len):
            if word1[j] != word2[j]:
                if word2[j] not in graph[word1[j]]:
                    graph[word1[j]].add(word2[j])
                    in_degree[word2[j]] += 1
                break

    # Find all nodes with in_degree 0
    queue = deque([c for c in chars if in_degree[c] == 0])
    result = []

    while queue:
        if len(queue) > 1:
            # If multiple choices, pick the lex smallest to ensure consistency
            queue = deque(sorted(queue))
        current = queue.popleft()
        result.append(current)

        for neighbor in graph[current]:
            in_degree[neighbor] -= 1
            if in_degree[neighbor] == 0:
                queue.append(neighbor)

    # Check if topological sort is possible (should be, given problem constraints)
    if len(result) != K:
        return ""

    return ''.join(result)
